// Rennspiel aus der Vogelperspektive: zwei Spuren, Autos kommen entgegen, Ueberholen zaehlt Punkte.
const TOP_Y = 520;

export default {
  title: "Überholen auf der Autobahn",
  controls: ["left", "right"],
  lives: 1,

  init(g) {
    return { lane: 1, x: 260, cars: [], dichte: 0.035, ueberholt: 0 };
  },

  update(s, input, g) {
    if (input.left) s.lane = 0;
    if (input.right) s.lane = 1;
    const tx = s.lane === 0 ? 100 : 260;
    const dx = tx - s.x;
    s.x += Math.sign(dx) * Math.min(6, Math.abs(dx));

    if (g.frame > 0 && g.frame % 300 === 0) s.dichte = g.random() < 0.5 ? 0.008 : 0.035;
    if (g.frame % 30 === 0) g.addScore(1);

    for (const c of s.cars) c.y += 3;

    for (const c of s.cars) {
      if (!c.gez && c.lane !== s.lane && c.y > TOP_Y + 35) {
        c.gez = true;
        s.ueberholt += 1;
        g.addScore(1);
        g.sound("pop");
      }
    }

    for (const c of s.cars) {
      if (c.lane === s.lane && Math.abs(c.y - TOP_Y) < 70) {
        s.cars = [];
        g.sound("hurt");
        g.loseLife();
        return;
      }
    }

    if (s.cars.length < 30) {
      for (const lane of [0, 1]) {
        if (g.random() < s.dichte) s.cars.push({ x: lane === 0 ? 100 : 260, y: -80, lane, gez: false });
      }
    }
    s.cars = s.cars.filter((c) => c.y <= g.H + 80);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, 48, 120, 592, "yellow", { round: 8 });
    d.rect(200, 48, 120, 592, "yellow", { round: 8 });
    for (const c of s.cars) d.emoji("🚙", c.x, c.y, 34);
    d.emoji("🏎️", s.x, TOP_Y, 36);
    d.text("Ueberholt: " + s.ueberholt, 352, 30, { size: 18, align: "right" });
  }
};

// Schaetzspiel (Runden-Vorlage): Gummibaerchen zaehlen, 5 Runden, Computer schaetzt mit.
const RUNDEN = 5, KI_ZEIT = 30, AUSW = 90, WIEDERHOLEN = 12;

export default {
  title: "Gummibärchen-Schätzspiel",
  controls: ["up", "down", "fire"],
  lives: 1,

  init(g) {
    return { runde: 1, glas: g.randInt(10, 60), schaetzung: 20, ki: null, gesch: null, rt: 0, halten: 0,
      punkte: 0, ki_punkte: 0, info: "Schätze, wie viele Bärchen im Glas sind!", ende: false };
  },

  update(s, input, g) {
    if (s.ende) return;
    // Zahl aendern: sofort beim Druecken, dann alle WIEDERHOLEN Frames, solange gehalten
    const dir = (input.up ? 1 : 0) - (input.down ? 1 : 0);
    if (dir !== 0) {
      if (s.halten % WIEDERHOLEN === 0) s.schaetzung = g.clamp(s.schaetzung + dir, 0, 99);
      s.halten += 1;
    } else s.halten = 0;
    // Schaetzen: jede Bestaetigung gibt sofort 1 Punkt
    if (input.firePressed) {
      s.gesch = s.schaetzung;
      s.punkte += 1;
      g.addScore(1);
      g.sound("pop");
    }
    s.rt += 1;
    if (s.rt === KI_ZEIT && s.ki === null) s.ki = g.randInt(0, 99);
    if (s.rt >= AUSW) auswerten(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Runde " + s.runde + " von " + RUNDEN, g.W / 2, 90, { size: 22, align: "center" });
    d.emoji("🫙", 180, 300, 150);
    for (let i = 0; i < s.glas; i++) {
      const col = i % 8, row = Math.floor(i / 8);
      d.emoji("🐻", 128 + col * 14, 236 + row * 16, 16);
    }
    d.text("Deine Schätzung: " + s.schaetzung, g.W / 2, 130, { size: 22, align: "center" });
    d.text("Computer: " + (s.ki === null ? "schätzt noch ..." : s.ki), g.W / 2, 162, { size: 18, align: "center" });
    d.text(s.gesch === null ? "Du bist dran" : "Geschätzt, warte auf Auswertung", g.W / 2, 500, { size: 18, align: "center" });
    d.text("Hoch/runter: ändern, Feuer: schätzen", g.W / 2, 530, { size: 16, align: "center" });
    d.text("Du " + s.punkte + "  :  Computer " + s.ki_punkte, g.W / 2, 565, { size: 22, align: "center" });
    d.text(s.info, g.W / 2, 605, { size: 14, align: "center" });
  }
};

function auswerten(s, g) {
  const dSp = s.gesch === null ? 999 : Math.abs(s.gesch - s.glas);
  const dKi = Math.abs(s.ki - s.glas);
  let txt = "Glas: " + s.glas + ". ";
  if (dSp < dKi) { s.punkte += 10; g.addScore(10); txt += "Du bist näher dran (+10)."; }
  else if (dKi < dSp) { s.ki_punkte += 10; txt += "Computer ist näher dran (+10)."; }
  else { s.punkte += 5; g.addScore(5); s.ki_punkte += 5; txt += "Gleichstand (je +5)."; }
  s.info = txt;
  if (s.runde >= RUNDEN) {
    s.ende = true;
    if (s.punkte > s.ki_punkte) g.win(); else g.gameOver();
    return;
  }
  s.runde += 1;
  s.glas = g.randInt(10, 60);
  s.gesch = null;
  s.ki = null;
  s.rt = 0;
  s.halten = 0;
  g.sound("level");
}

// Ueberhol-Rennen: Rennwagen auf zwei Spuren, fremde Autos ueberholen, Zusammenstoss beendet die Fahrt.
export default {
  title: "Überhol-Rennen auf der Autobahn",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return { me: { x: 250, y: 520, w: 40, h: 60 }, cars: [], ueberholt: 0, road: 0 };
  },

  update(s, input, g) {
    if (input.left) s.me.x -= 6;
    if (input.right) s.me.x += 6;
    s.me.x = g.clamp(s.me.x, 70, 250);

    const tempo = 4 + 0.4 * Math.floor(s.ueberholt / 10);
    s.road = (s.road + tempo) % 60;

    const pl = s.me.x < 160 ? 0 : 1;
    if (g.frame >= 30 && g.random() < 0.03) {
      // Meist auf der anderen Spur, damit Ueberholen moeglich ist; manchmal auf der eigenen Spur.
      const lane = g.random() < 0.75 ? 1 - pl : pl;
      s.cars.push({ x: lane === 0 ? 70 : 250, y: -60, w: 40, h: 60, lane, counted: false });
    }

    for (const c of s.cars) {
      c.y += tempo;
      if (g.hit(s.me, c)) { g.sound("lose"); g.gameOver(); return; }
      if (!c.counted && c.y > s.me.y + s.me.h && c.lane !== pl) {
        c.counted = true;
        s.ueberholt += 1;
        g.addScore(1);
        g.sound("pop");
        if (s.ueberholt % 10 === 0) g.nextLevel();
      }
    }
    s.cars = s.cars.filter((c) => c.y < g.H);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink");
    for (let y = g.TOP - 60 + s.road; y < g.H; y += 60) d.rect(176, y, 8, 30, "yellow");
    for (const c of s.cars) d.emoji("🚙", c.x + 20, c.y + 30, 50);
    d.emoji("🏎️", s.me.x + 20, s.me.y + 30, 56);
    d.text("Überholt: " + s.ueberholt, 20, 30, { size: 22, color: "ink", align: "left" });
  }
};

// Ueberhol-Rennen: Spielauto wechselt zwischen zwei Spuren, andere Autos kommen von vorne.
// Start auf der rechten Spur, damit Links-Wechsel von Anfang an moeglich ist.
const LANES = [110, 250];
const PY = 520;

export default {
  title: "Überhol-Rennen auf der Autobahn",
  controls: ["left", "right", "up", "down"],
  lives: 5,

  init(g) {
    return { lane: 1, v: 4, sw: 12, cars: [], tick: 0, next: 90, safe: 0, off: 0 };
  },

  update(s, input, g) {
    s.sw += 1;
    if ((input.left || input.right) && s.sw >= 12) {
      const want = input.left ? 0 : 1;
      if (want !== s.lane) { s.lane = want; s.sw = 0; }
    }
    if (input.up) s.v = Math.min(8, s.v + 0.1);
    if (input.down) s.v = Math.max(2, s.v - 0.1);
    s.off += s.v;

    s.tick += 1;
    if (s.tick >= s.next) {
      s.tick = 0;
      s.next = 90 + g.randInt(0, 30);
      // Zufaellige Spur; meist die Spur neben dem Spielauto, damit Ueberholen moeglich ist
      let li = g.randInt(0, 1);
      if (li === s.lane && g.random() < 0.7) li = 1 - li;
      s.cars.push({ li, x: LANES[li], y: g.TOP - 40, passed: false, gone: false });
    }

    if (s.safe > 0) s.safe -= 1;
    const pl = { x: LANES[s.lane] - 20, y: PY - 30, w: 40, h: 60 };
    for (const c of s.cars) {
      if (c.gone) continue;
      c.y += 0.5 * s.v + 0.1 * g.level;
      if (!c.passed && c.y > PY + 60) {
        c.passed = true;
        if (c.li !== s.lane) { g.addScore(1); g.sound("pop"); }
        continue;
      }
      if (!c.passed && s.safe === 0 && g.hit(pl, { x: c.x - 18, y: c.y - 28, w: 36, h: 56 })) {
        c.gone = true;
        s.v = 2;
        s.safe = 60;
        g.sound("hurt");
        g.loseLife();
      }
    }
    s.cars = s.cars.filter((c) => !c.gone && c.y < g.H + 40);

    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink");
    d.rect(40, g.TOP, 4, g.H - g.TOP, "yellow");
    d.rect(316, g.TOP, 4, g.H - g.TOP, "yellow");
    for (let y = g.TOP - 60 + (s.off % 60); y < g.H; y += 60) d.rect(178, y, 4, 36, "yellow");
    for (const c of s.cars) d.emoji("🚙", c.x, c.y, 36);
    const px = LANES[s.lane];
    if (s.safe > 0) {
      const col = (s.safe >> 2) % 2 === 0 ? "red" : "cream";
      d.rect(px - 24, PY - 34, 48, 68, col, { round: 12 });
    }
    d.emoji("🏎️", px, PY, 40);
  }
};

// Gummibaerchen-Schaetzspiel: 3 Runden, Tipp per Pfeiltasten, Computer schaetzt mit. Naehere Schaetzung gewinnt die Runde.
export default {
  title: "Gummibärchen-Schätzspiel",
  controls: ["up", "down", "fire"],
  lives: 1,

  init(g) {
    const glas = g.randInt(20, 80);
    return {
      runde: 1, glas, tipp: 50,
      komp: g.clamp(glas + g.randInt(-12, 12), 0, 200),
      siegSp: 0, siegKomp: 0, phase: "tipp", zaehler: 0, halten: 0,
      msg: "Schätze die Anzahl!"
    };
  },

  update(s, input, g) {
    if (s.phase === "zeigen") {
      s.zaehler -= 1;
      if (s.zaehler > 0) return;
      if (s.runde < 3) {
        s.runde += 1;
        s.glas = g.randInt(20, 80);
        s.komp = g.clamp(s.glas + g.randInt(-12, 12), 0, 200);
        s.tipp = 50;
        s.phase = "tipp";
        s.msg = "Neue Runde: Schätze!";
        return;
      }
      if (s.siegSp >= 2) { s.msg = "Gesamtsieger: du!"; g.win(); }
      else { s.msg = "Gesamtsieger: Computer"; g.gameOver(); }
      return;
    }

    const dir = (input.up ? 1 : 0) - (input.down ? 1 : 0);
    if (dir !== 0) {
      if (s.halten % 10 === 0) s.tipp = g.clamp(s.tipp + dir, 0, 200);
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;

    g.addScore(1);
    const p = Math.abs(s.tipp - s.glas);
    const k = Math.abs(s.komp - s.glas);
    if (p < k) { s.siegSp += 1; g.addScore(10); s.msg = "Runde an dich"; g.sound("coin"); }
    else if (k < p) { s.siegKomp += 1; s.msg = "Runde an den Computer"; g.sound("pop"); }
    else s.msg = "Gleichstand, keiner gewinnt";
    s.phase = "zeigen";
    s.zaehler = 120;
  },

  draw(s, d) {
    d.clear("cream");
    d.text("Runde " + s.runde + " von 3", 180, 80, { size: 20, align: "center" });
    d.rect(110, 120, 140, 200, "cream", { round: 12, line: true });
    for (let i = 0; i < s.glas; i++) {
      const col = i % 8, row = Math.floor(i / 8);
      d.circle(120 + col * 16, 130 + row * 16, 6, "red");
    }
    if (s.phase === "tipp") {
      d.text("Dein Tipp: " + s.tipp, 180, 380, { size: 24, align: "center" });
    } else {
      d.text("Dein Tipp: " + s.tipp + "  Computer: " + s.komp + "  Glas: " + s.glas, 180, 400, { size: 16, align: "center" });
      d.text(s.msg, 180, 430, { size: 20, align: "center" });
      if (s.runde === 3) d.text("Gesamt: " + s.siegSp + " : " + s.siegKomp, 180, 470, { size: 20, align: "center" });
    }
    d.emoji("🍬", 180, 440, 48);
  }
};
